from collections import Counter

def word_count(text: str) -> int:
    # A word is a maximal run of ASCII letters, digits and apostrophes (').
    # Words are compared case-insensitively and reported in lower case.
    words = re.findall(r"[a-zA-Z0-9']+", text.lower())
    return len(words)

def char_frequency(text: str) -> dict[str, int]:
    # counts of the ASCII letters a-z in `text`, case-insensitive;
    # only letters that occur are keys.
    freq = Counter()
    for char in text.lower():
        if 'a' <= char <= 'z':
            freq[char] += 1
    return dict(freq)

def average_word_length(text: str) -> float:
    # mean word length rounded to 2 decimals;
    # 0.0 when there are no words.
    words = re.findall(r"[a-zA-Z0-9']+", text.lower())
    if not words:
        return 0.0
    total_length = sum(len(word) for word in words)
    return round(total_length / len(words), 2)

def sentence_count(text: str) -> int:
    # each maximal run of `.`, `!` or `?` ends one sentence;
    # if words appear after the last run (or there is no run at all) that trailing text counts
    # as one more sentence. Text without words returns 0.
    if not re.search(r'[a-zA-Z0-9']', text):
        return 0

    terminator_matches = list(re.finditer(r'[.!?]+', text))
    sentence_count = len(terminator_matches)

    if not terminator_matches:
        return 1

    last_terminator_end = terminator_matches[-1].end()
    trailing_text = text[last_terminator_end:]

    if trailing_text.strip():
        sentence_count += 1

    return sentence_count

def top_words(text: str, n: int) -> list[tuple[str, int]]:
    # the `n` most frequent lower-cased words as (word, count) tuples,
    # sorted by count (descending) then word (ascending).
    # Returns [] when n <= 0.
    if n <= 0:
        return []

    words = re.findall(r"[a-zA-Z0-9']+", text.lower())
    word_counts = Counter(words)

    # Sort by count (descending) then word (ascending)
    sorted_words = sorted(word_counts.items(), key=lambda item: (-item[1], item[0]))

